"""Human-readable research report from complete verified result tables."""
import collections,gzip,json
from pathlib import Path
P=Path(__file__).resolve().parent
def read(p):return json.loads((P/p).read_bytes())
def f(x):return f'{x:.2f}'.replace('.',',')
names={'none':'Первое доступное по порядку','pose_cycle':'Следующее по текущей позиции','cursor':'Последнее проверенное место','full':'Все проверенные места','trained':'Все места + частоты по 39 train'}
def main():
    r=read('results.json');overall=r['overall']['arms'];pr=r['step_contrasts'];cross=read('interface_comparison.json')
    unseen=read('roster.json')['valid_unseen'];floors=collections.Counter(g['floorplan'] for g in unseen)
    lines=['# ALFWorld только по текстовой обратной связи','',
      'Полностью разыграны 134 игры официальной текстовой выборки valid_unseen, по пять условий в каждой. На любом шаге агент видел только инструкцию, текст обстановки и текстовый ответ на собственную команду. После 50 действий исполнение останавливалось. Контроллер использовал фиксированные шаблоны команд и грамматику бытовых задач. Модель и видеокарта в этой серии не участвовали. При запуске TextWorld запрашивался только флаг победы для внешнего оценщика. [ALFWorld, ICLR 2021](https://arxiv.org/abs/2010.03768)','',
      '| Правило поиска | Победы из 134 | Среднее число действий¹ | Выполнено действий | Ответ «Nothing happens» | Максимум дополнительно записанных мест |',
      '|---|---:|---:|---:|---:|---:|']
    for a in names:
        s=overall[a];lines.append(f"| {names[a]} | {s['won']} | {f(s['mean_capped_steps'])} | {s['attempts']} | {s['nothing_happens']} | {s['max_extra_search_entries']} |")
    lines+=['','¹ Каждая нерешённая задача в среднем получает стоимость 50. Фактические попытки считаются и при отрицательном ответе симулятора. В отдельном поле unrecognized записано число действий, для которых контроллер не распознал подтверждение успеха. Всего выполнено '+str(r['actual_actions'])+' действий на 670 невиданных ранее разыгрываниях (5 условий × 134 одинаковых задания).','',
      '## Что именно считается памятью','',
      'Каждому варианту доступны видимые при входе названия мест, текущая позиция, инвентарь, выбранный подэтап и уже доставленные предметы. Простейший контроль всегда берёт первый пункт общего списка, отличный от текущего. Поэтому он может чередовать два места. Более сильный контроль вычисляет следующий пункт циклического списка прямо по текущей позиции. Для него нужно ноль дополнительных записей о прошлых поисках. Курсор отдельной переменной сохраняет только последнее осмотренное место. Полная история хранит список осмотров до смены подэтапа. Тренировочный вариант ранжирует типы мест по числу увиденных там целевых предметов. Контроллер извлекает объекты и состояния дверей из строк симулятора. Полнота получаемых при входе списков и ограниченная грамматика упрощают эту среду. [Закреплённая грамматика](https://github.com/alfworld/alfworld/blob/aaba6870f86c5be6a08a491f32a50b906227bc3e/alfworld/data/alfred.twl2)',
      '',f"Последовательности всех команд курсора и циклического обхода по текущей позиции совпали в {r['identical_to_pose_action_traces']['cursor']} из 134 игр. Для полной истории совпадение с обходом по позиции было в {r['identical_to_pose_action_traces']['full']} играх. Сравнение количества побед простого порядка с курсором само по себе смешивает порядок навигации с записью прошлого. Команды совпавших условий исполнялись в отдельных физических разыгрываниях.",'',
      '## Цена поиска на тех же играх','',
      '| Разность (первый вариант минус второй) | Разность действий на игру | 95% парный bootstrap игр | 95% bootstrap планировок | Меньше / больше / одинаково действий |',
      '|---|---:|---:|---:|---:|']
    for label,x in pr.items():
        a,b=label.split('-');I=x['paired_task_boot95'];J=x['floorplan_boot95']
        lines.append(f"| {names[a]} − {names[b]} | {f(x['mean_delta_steps'])} | [{f(I[0])}, {f(I[1])}] | [{f(J[0])}, {f(J[1])}] | {x['fewer']} / {x['more']} / {x['equal']} |")
    lines+=['',f"Четыре планировки неодинаково представлены, число задач по ним — {', '.join(k+' ('+str(v)+')' for k,v in floors.most_common())}. Для интервальных оценок выполнены 5 000 парных повторных выборок по играм и отдельно по планировкам. Четырёх кластеров мало для точной оценки переноса на новые дома. Попарные выигрыши, проигрыши, совпадения, интервалы по доле побед и точный тест по дискордантным исходам записаны в results.json.",'',
    '## Что дала тренировка','',
    '39 новых траекторий разведчика на заранее выбранных тренировочных заданиях дали 1 302 выполненных действия, наблюдения в 879 местах и 57 типов найденных объектов. Использовались только доступные строки симулятора. Разведчик открывал явно закрытые места, шёл по фиксированному порядку и учитывал тип вещи не более одного раза на место в игре. Это необработанные частоты встречаемости, они зависят от охвата разведчика. Шесть тренировочных игр использованы для проверки грамматики. Затем хеш политики и частот был закреплён до запуска всех 134 игр.',
    '', '## Результаты по семействам заданий','',
    '| Семейство | Заданий | Первый пункт | Цикл по позиции | Курсор | Все осмотры | С частотами |',
    '|---|---:|---:|---:|---:|---:|---:|']
    for fam,x in r['families'].items():
        lines.append('| '+' | '.join([fam,str(x['n'])]+[str(x['arms'][a]['won']) for a in names])+' |')
    lines+=['','## Успех до заданного числа действий','',
    '| Бюджет | Первый пункт | Цикл по позиции | Курсор | Все осмотры | С частотами |','|---|---:|---:|---:|---:|---:|']
    for h in (10,20,30,40,50):
        lines.append('| '+' | '.join([str(h)]+[str(r['horizon_sensitivity'][str(h)][a]) for a in names])+' |')
    lines+=['','Числа для укороченных бюджетов получены отсечением фактически исполненной траектории. Если сообщить меньший бюджет контроллеру заранее, он мог бы выбирать другие действия.',
    '', '## Сопоставление с прежним доступом к меню','',
    '| Правило | Ранее с меню, победы | Сейчас по тексту, победы | Полностью совпавшие цепочки действий |',
    '|---|---:|---:|---:|']
    for arm,x in cross.items():
        lines.append(f"| {names[arm]} | {x['menu_wins']} | {x['text_wins']} | {x['identical_action_sequence']} |")
    lines+=['','Сопоставление интерфейсов описательное. Новая политика получает текст, по-своему отслеживает текущий обзор и использует частоты заново исполненных тренировочных разведок. Частоты прежней системы и списки допустимых команд закрытых игр не передавались. Политика общего назначения потребовала бы отдельно освоить парсинг, грамматику и подэтапы. ReAct публиковал результаты на 134 unseen-играх с LLM и размеченными демонстрациями. Эти различия мешают переносить результат данного контроллера в таблицу лидеров языковых агентов. [ReAct, раздел 4](https://arxiv.org/html/2210.03629)',
    '','## Перепроверка','',
    'Из этого каталога выполнить `python audit.py --check`. Нужна стандартная библиотека Python. Верификатор выводит все собственные действия заново из текстов прошлых наблюдений, проверяет тренировочный набор частот, хеши, финальные флаги и парную статистику. Физический повтор запуска TextWorld описан в REPRODUCE.md. Журналы всех действий находятся в eval/ и train/, точный список задач — в roster.json, 134 строки с исходами условий — в per_episode.csv.']
    (P/'summary_ru.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
if __name__=='__main__':main()
